import json,hashlib
P=Path(__file__).resolve().parent;V=P/'original-action-video-v1';V.mkdir(exist_ok=True)
master=Image.open(P/'master-native.png').convert('RGBA');large=master.resize((768,768),Image.Resampling.NEAREST)
plate=Image.new('RGB',large.size,(12,18,24));plate.paste(large,(0,0),large);plate.save(V/'master-input.png')
prompt='''Locked camera, one full-body West-facing woman in the supplied exact station-suit artwork, facing left. Animate ONE quiet scientific scanner interaction, not walking. First second: hold original standing stance. Then smoothly bend both elbows and draw the small handheld scanner from her belt, hold it in both gloved hands just in front of her lower chest, briefly operate its tiny cyan screen, then smoothly return it to the belt and lower her arms. Finish in the exact original standing pose and hold still for the final second. Both boots remain planted at their original locations throughout; legs, hips, torso and head stay in their original size and position. Continuous sleeves pivot naturally from the original shoulders, no detached arms or new body parts. Preserve original small head, dark brown bun, warm matte skin, fine face detail, original neutral dark charcoal cloth and quilted texture, panel layout, shoulder patch, belt equipment, metallic knee pads and boots. Do not brighten the suit, smooth its detail, enlarge the head, shift her body, change perspective or introduce blue-grey grading. The scanner screen is tiny cyan, with no cast light on her. Same flat dark background, no scenery, shadows, glow or camera motion. No repeated action cycles. Only the arm and hand action moves; original appearance and stance remain fixed.'''
